#(
    parameter NUM_SLAVES = 5,
    parameter BRIDGE_ID = 3,  // Unique ID for this master
    parameter BRIDGE_ID_WIDTH = 2,
    parameter SKID_DEPTH_AW = 2,
    parameter SKID_DEPTH_W = 4,
    parameter SKID_DEPTH_B = 2
) (
    input  logic aclk,
    input  logic aresetn,

    // External AXI interface (from inj_wr master)
    input  logic [7:0]  inj_wr_awid,
    input  logic [31:0]  inj_wr_awaddr,
    input  logic [7:0]  inj_wr_awlen,
    input  logic [2:0]  inj_wr_awsize,
    input  logic [1:0]  inj_wr_awburst,
    input  logic         inj_wr_awlock,
    input  logic [3:0]  inj_wr_awcache,
    input  logic [2:0]  inj_wr_awprot,
    input  logic [3:0]  inj_wr_awqos,
    input  logic [3:0]  inj_wr_awregion,
    input  logic         inj_wr_awuser,
    input  logic         inj_wr_awvalid,
    output  logic         inj_wr_awready,

    input  logic [127:0]  inj_wr_wdata,
    input  logic [15:0]  inj_wr_wstrb,
    input  logic         inj_wr_wlast,
    input  logic         inj_wr_wuser,
    input  logic         inj_wr_wvalid,
    output  logic         inj_wr_wready,

    output  logic [7:0]  inj_wr_bid,
    output  logic [1:0]  inj_wr_bresp,
    output  logic         inj_wr_buser,
    output  logic         inj_wr_bvalid,
    input  logic         inj_wr_bready,

    // Address decode outputs (full width one-hot)
    output logic [NUM_SLAVES-1:0] slave_select_aw,
    output logic [BRIDGE_ID_WIDTH-1:0] bridge_id_aw,

    // 128b width outputs (to crossbar)
    output axi4_aw_t     inj_wr_128b_aw,
    output logic         inj_wr_128b_awvalid,
    input  logic         inj_wr_128b_awready,

    output axi4_w_128b_t  inj_wr_128b_w,
    output logic         inj_wr_128b_wvalid,
    input  logic         inj_wr_128b_wready,

    input  axi4_b_t      inj_wr_128b_b,
    input  logic         inj_wr_128b_bvalid,
    output logic         inj_wr_128b_bready
);

    // ================================================================
    // Localparams
    // ================================================================
    localparam ADDR_WIDTH = 32;
    localparam DATA_WIDTH = 128;
    localparam ID_WIDTH = 8;

    // ================================================================
    // Internal signals after wrapper (timing isolation)
    // Note: ID width matches external (8-bit)
    // ================================================================
    logic [7:0]   fub_axi_awid;
    logic [31:0]  fub_axi_awaddr;
    logic [7:0]   fub_axi_awlen;
    logic [2:0]   fub_axi_awsize;
    logic [1:0]   fub_axi_awburst;
    logic         fub_axi_awlock;
    logic [3:0]   fub_axi_awcache;
    logic [2:0]   fub_axi_awprot;
    logic [3:0]   fub_axi_awqos;
    logic [3:0]   fub_axi_awregion;
    logic         fub_axi_awuser;
    logic         fub_axi_awvalid;
    logic         fub_axi_awready;

    logic [127:0]  fub_axi_wdata;
    logic [15:0]   fub_axi_wstrb;
    logic         fub_axi_wlast;
    logic         fub_axi_wuser;
    logic         fub_axi_wvalid;
    logic         fub_axi_wready;

    logic [7:0]   fub_axi_bid;
    logic [1:0]   fub_axi_bresp;
    logic         fub_axi_bvalid;
    logic         fub_axi_bready;

    logic         wrapper_wr_busy;

    // Master-unique fabric IDs: {BRIDGE_ID, id} (bridge TASK-005, was BRIDGE-016). Responses
    // return with the prefix; the response muxes select the low bits.
    logic [XBAR_ID_WIDTH-1:0] xbar_axi_awid;
    assign xbar_axi_awid = {BRIDGE_ID_WIDTH'(BRIDGE_ID), MASTER_ID_WIDTH'(fub_axi_awid)};

    // ================================================================
    // Timing isolation wrapper (axi4_slave_wr)
    // ================================================================
    axi4_slave_wr #(
        .SKID_DEPTH_AW(SKID_DEPTH_AW),
        .SKID_DEPTH_W(SKID_DEPTH_W),
        .SKID_DEPTH_B(SKID_DEPTH_B),
        .AXI_ID_WIDTH(8),
        .AXI_ADDR_WIDTH(32),
        .AXI_DATA_WIDTH(128),
        .AXI_USER_WIDTH(1)
    ) u_timing_wrapper_wr (
        .aclk(aclk),
        .aresetn(aresetn),

        // External side (s_axi)
        .s_axi_awid(inj_wr_awid),
        .s_axi_awaddr(inj_wr_awaddr),
        .s_axi_awlen(inj_wr_awlen),
        .s_axi_awsize(inj_wr_awsize),
        .s_axi_awburst(inj_wr_awburst),
        .s_axi_awlock(inj_wr_awlock),
        .s_axi_awcache(inj_wr_awcache),
        .s_axi_awprot(inj_wr_awprot),
        .s_axi_awqos(inj_wr_awqos),
        .s_axi_awregion(inj_wr_awregion),
        .s_axi_awuser(inj_wr_awuser),
        .s_axi_awvalid(inj_wr_awvalid),
        .s_axi_awready(inj_wr_awready),
        .s_axi_wdata(inj_wr_wdata),
        .s_axi_wstrb(inj_wr_wstrb),
        .s_axi_wlast(inj_wr_wlast),
        .s_axi_wuser(inj_wr_wuser),
        .s_axi_wvalid(inj_wr_wvalid),
        .s_axi_wready(inj_wr_wready),
        .s_axi_bid(inj_wr_bid),
        .s_axi_bresp(inj_wr_bresp),
        .s_axi_buser(inj_wr_buser),
        .s_axi_bvalid(inj_wr_bvalid),
        .s_axi_bready(inj_wr_bready),

        // Bridge-internal side (fub_axi)
        .fub_axi_awid(fub_axi_awid),
        .fub_axi_awaddr(fub_axi_awaddr),
        .fub_axi_awlen(fub_axi_awlen),
        .fub_axi_awsize(fub_axi_awsize),
        .fub_axi_awburst(fub_axi_awburst),
        .fub_axi_awlock(fub_axi_awlock),
        .fub_axi_awcache(fub_axi_awcache),
        .fub_axi_awprot(fub_axi_awprot),
        .fub_axi_awqos(fub_axi_awqos),
        .fub_axi_awregion(fub_axi_awregion),
        .fub_axi_awuser(fub_axi_awuser),
        .fub_axi_awvalid(fub_axi_awvalid),
        .fub_axi_awready(fub_axi_awready),
        .fub_axi_wdata(fub_axi_wdata),
        .fub_axi_wstrb(fub_axi_wstrb),
        .fub_axi_wlast(fub_axi_wlast),
        .fub_axi_wuser(fub_axi_wuser),
        .fub_axi_wvalid(fub_axi_wvalid),
        .fub_axi_wready(fub_axi_wready),
        .fub_axi_bid(fub_axi_bid),
        .fub_axi_bresp(fub_axi_bresp),
        .fub_axi_buser(1'b0),
        .fub_axi_bvalid(fub_axi_bvalid),
        .fub_axi_bready(fub_axi_bready),

        // Status (empty connector = unconnected tie-off)
        .busy(wrapper_wr_busy)
    );

    logic [NUM_SLAVES-1:0] b_slave_select;
    logic [NUM_SLAVES-1:0] w_slave_select;

    // ================================================================
    // Address decode (slave selection) - Write
    // Slave 0 (ddr): 0x00000000 - 0x3FFFFFFF
    // Slave 4 (subtractive): 0x00000000 - 0xFFFFFFFF
    // ================================================================
    logic [NUM_SLAVES-1:0] comb_slave_select_aw;
    always_comb begin
        comb_slave_select_aw = '0;
        if (fub_axi_awaddr <= 32'h3FFFFFFF) begin
            comb_slave_select_aw[0] = 1'b1;  // ddr
        end
        else begin  // Full address range (catch-all)
            comb_slave_select_aw[4] = 1'b1;  // subtractive
        end
    end

    // Bridge ID for write channel (constant - tied to BRIDGE_ID parameter)
    assign bridge_id_aw = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Width adaptation - Master: 128b
    // Connected to slaves with widths: [128]
    // ================================================================

    // Per-width path-active gates (see comment in adapter_generator.py).
    logic aw_gate_ok;
    logic aw_path_active_128b;
    assign aw_path_active_128b = (comb_slave_select_aw[0] | comb_slave_select_aw[4]) && aw_gate_ok;
    logic w_path_active_128b;
    assign w_path_active_128b = w_slave_select[0] | w_slave_select[4];
    logic b_path_active_128b;
    assign b_path_active_128b = b_slave_select[0] | b_slave_select[4];

    // ================================================================
    // Direct passthrough: 128b → 128b (no converter)
    // Requests: fub_axi_* → inj_wr_128b_*
    // Responses: inj_wr_128b_* → MUX → fub_axi_*
    // ================================================================

    // AW channel (request: fub → output)
    assign inj_wr_128b_aw.id     = xbar_axi_awid;
    assign inj_wr_128b_aw.addr   = fub_axi_awaddr;
    assign inj_wr_128b_aw.len    = fub_axi_awlen;
    assign inj_wr_128b_aw.size   = fub_axi_awsize;
    assign inj_wr_128b_aw.burst  = fub_axi_awburst;
    assign inj_wr_128b_aw.lock   = fub_axi_awlock;
    assign inj_wr_128b_aw.cache  = fub_axi_awcache;
    assign inj_wr_128b_aw.prot   = fub_axi_awprot;
    assign inj_wr_128b_aw.qos    = fub_axi_awqos;
    assign inj_wr_128b_aw.region = fub_axi_awregion;
    assign inj_wr_128b_aw.user   = fub_axi_awuser;
    assign inj_wr_128b_awvalid   = fub_axi_awvalid && aw_path_active_128b;
    // awready routed via MUX

    // W channel (request: fub → output)
    assign inj_wr_128b_w.data  = fub_axi_wdata;
    assign inj_wr_128b_w.strb  = fub_axi_wstrb;
    assign inj_wr_128b_w.last  = fub_axi_wlast;
    assign inj_wr_128b_w.user  = fub_axi_wuser;
    assign inj_wr_128b_wvalid  = fub_axi_wvalid && w_path_active_128b;
    // wready routed via MUX

    // B channel (response: output → MUX → fub)
    // Ready gated by the response head — see b_path_active comment.
    assign inj_wr_128b_bready = fub_axi_bready && b_path_active_128b;
    // bid, bresp, bvalid routed via MUX (user field ignored)

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    // -------- AW per-ID target table (fixes bridge GitHub #119 L1) --------
    // 16 entries indexed by the ID's low 4 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AW_IDT_N = 16;
    logic [AW_TRK_AW:0]   aw_idt_cnt [AW_IDT_N];
    logic [NUM_SLAVES-1:0] aw_idt_tgt [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt;
    logic [3:0] aw_idt_widx, aw_idt_ridx;
    logic aw_idt_push, aw_idt_pop;
    assign aw_idt_widx = fub_axi_awid[3:0];
    assign aw_idt_ridx = fub_axi_bid[3:0];
    assign aw_idt_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_idt_pop  = fub_axi_bvalid && fub_axi_bready;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= '0;
                aw_idt_tgt[i] <= '0;
            end
            aw_out_cnt <= '0;
        end else begin
            if (aw_idt_push) aw_idt_tgt[aw_idt_widx] <= comb_slave_select_aw;
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= aw_idt_cnt[i]
                    + (AW_TRK_AW+1)'(aw_idt_push && (aw_idt_widx == 4'(i)))
                    - (AW_TRK_AW+1)'(aw_idt_pop  && (aw_idt_ridx == 4'(i)));
            end
            aw_out_cnt <= aw_out_cnt + (AW_TRK_AW+1)'(aw_idt_push)
                                          - (AW_TRK_AW+1)'(aw_idt_pop);
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AW_TRK_DEPTH is the port's outstanding limit.
    logic aw_trk_full, aw_id_ok;
    assign aw_trk_full = (aw_out_cnt == (AW_TRK_AW+1)'(AW_TRK_DEPTH));
    assign aw_id_ok    = (aw_idt_cnt[aw_idt_widx] == '0) ||
                           (aw_idt_tgt[aw_idt_widx] == comb_slave_select_aw);

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign b_slave_select = 5'b00001;

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // A new AW may target a different slave only once every W burst
    // already accepted has gone: W carries no ID and follows AW order,
    // so two masters each with W owed to two slaves could otherwise
    // wait on each other at the slaves' W ports (crossed W deadlock).
    assign aw_gate_ok = aw_id_ok && !aw_trk_full &&
                        ((w_trk_wptr == w_trk_rptr) ||
                         (w_slave_select == comb_slave_select_aw));

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            5'b00001: begin  // Slave 0 (128b)
                fub_axi_awready = inj_wr_128b_awready;
            end
            5'b10000: begin  // Slave 4 (128b)
                fub_axi_awready = inj_wr_128b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AW the gate refuses (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            5'b00001: begin  // Slave 0 (128b)
                fub_axi_wready = inj_wr_128b_wready;
            end
            5'b10000: begin  // Slave 4 (128b)
                fub_axi_wready = inj_wr_128b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    always_comb begin
        fub_axi_bid = 8'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;

        case (b_slave_select)
            5'b00001: begin  // Slave 0 (128b)
                fub_axi_bid = inj_wr_128b_b.id[7:0];
                fub_axi_bresp = inj_wr_128b_b.resp;
                fub_axi_bvalid = inj_wr_128b_bvalid;
            end
            5'b10000: begin  // Slave 4 (128b)
                fub_axi_bid = inj_wr_128b_b.id[7:0];
                fub_axi_bresp = inj_wr_128b_b.resp;
                fub_axi_bvalid = inj_wr_128b_bvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

endmodule : bridge_fb_data_inj_wr_adapter
